"use strict";
const campusKey='olddays-campus-case-02',campusEvidenceKeys=['sms','photo','qq','repair','forum','audio'];
let campus={started:false,evidence:[],solved:false,hints:0,device:'',ending:'',notes:''},campusPanel='',campusFeedback='',campusPhotoBack=false;
try{const p=JSON.parse(localStorage.getItem(campusKey)||'null');if(p){campus.notes=typeof p.notes==='string'?p.notes.slice(0,1200):'';campus.started=p.started===true;campus.evidence=campusEvidenceKeys.filter(k=>p.evidence?.includes(k));campus.solved=p.solved===true&&campus.evidence.length===6;campus.hints=Math.max(0,Math.min(3,Number(p.hints)||0));campus.device=Object.hasOwn(phoneModels,p.device)?p.device:'symbian';campus.ending=campus.solved?'returned':'';}}catch{}
function saveCampus(){try{localStorage.setItem(campusKey,JSON.stringify(campus));return true;}catch{return false;}}
const campusClues={
 sms:{title:'未署名短信 / 借来的手机',body:'“别相信那个七点十七的来电传说。手机是我借的，不是我的。那晚广播以后，我把手机留在了东楼维修箱。报名单的照片还在相册。——遥”\n短信附件：报名单.jpg、最后一段试音.wav、维修单.txt。号码0717只是广播社玩笑用的服务短号，不是手机密码。'},
 photo:{title:'相册 / 广播社报名单',body:'照片里是贴在音乐教室门口的报名单。\n设备栏：蓝色手机，物主签名“听风”；借用人：周遥。\n合照背面写着：“陈默总说，风里有听不见的歌。”\n报名日期被贴纸盖住了一角，仅能辨认六月。'},
 qq:{title:'QQ / 小夏的离线留言',body:'小夏 18:42：听风是陈默的网名呀。周遥只是借他的手机录试音。不要看到短信落款，就把东西交给周遥。\n小夏 18:44：他那阵子按生日设了手机锁。具体哪天？维修师傅那里有登记。\n小夏 18:46：我在动漫社等你，把真相查清再来聊新一集。'},
 repair:{title:'通讯录 / 修机师傅留下的维修单',body:'送修登记：蓝色手机，六月十二日。\n物主：陈同学，签名“听风”。生日：6月12日；物主授权由本人领取。\n故障说明：定时响起一段铃声；检查结果：手机未设置闹钟，声音来自广播教室的旧录音机。\n师傅批注：四位锁码按月日写，不是来电短号。'},
 forum:{title:'校园BBS / 东楼七点十七的传说',body:'1楼 [晚自习路过]：每天晚上七点十七，空教室就响起同一段铃声。是不是以前毕业的人回来了？\n2楼 [周遥]：我是那晚负责放带的人。广播社19:17试音，旧录音机忘了关定时播放。\n3楼 [器材管理员]：已核对值班本与定时开关，都是19:17。这个故事是误传，没发生失踪事件。\n4楼 [小夏]：请保留传说，也请把真实的物主找回来。'},
 audio:{title:'音乐播放器 / 最后一段试音',body:'录音旁的手写标记：19:17，广播社试音。\n听完，传说里的“怪声”其实是一段循环旋律；背景有人说：“遥，把陈默的手机还给他，明天还要带去动漫社。”\n这是本站虚构案件的文字转录；下方播放的是原创合成示意音，不冒充真实人物录音。'}
};
function campusLink(panel,label){return `<button class="campus-link" data-campus="${panel}">${label}</button>`;}
function campusCollect(key){if(!campus.started||!campusEvidenceKeys.includes(key))return false;if(!campus.evidence.includes(key))campus.evidence.push(key);saveCampus();return true;}
function campusSolve(owner,code,truth){if(campus.evidence.length!==6)return '证据还没齐。短信、相册、QQ、维修单、论坛和录音，六处需要互相核对。';if(owner!=='chen'||code!=='0612'||truth!=='broadcast')return '推理还对不上。借用人不等于物主，来电短号也不等于锁码；再核对签名、维修单和定时记录。';campus.solved=true;campus.ending='returned';saveCampus();return '你把手机交还陈默。周遥只是借用人，0612来自生日，19:17的铃声来自广播社旧录音机的定时试音。传说里没有失踪的人，只有一段没有及时解释的回忆。';}
function campusMarkup(){const clue=campusClues[campusPanel];if(clue)return `<section class="campus-paper"><small>原创校园传说 · 第02案 / 虚构线索</small><h2>${clue.title}</h2>${campusPanel==='photo'?`<figure class="campus-photo ${campusPhotoBack?'photo-back':''}"><b>${campusPhotoBack?'照片背面的字':'校园广播社'}</b><span>${campusPhotoBack?'陈默总说，风里有听不见的歌。':'蓝色手机 / 听风<br>借用人：周遥'}</span><i>六月的风，写在照片背面。</i></figure><button data-campus-photo-turn>${campusPhotoBack?'翻回照片正面':'把照片翻过来'}</button>`:''}<p>${campusPanel==='photo'&&!campusPhotoBack?'正面是一张设备出借登记：物主签名“听风”，借用人周遥。照片背面似乎还有一行铅笔字。':clue.body}</p>${campusPanel==='audio'?'<audio controls preload="none" src="audio/moon-letter.mp3" aria-label="案件原创示意音"></audio>':''}${campusPanel==='photo'&&!campusPhotoBack?'<small>翻到照片背面，才算看全这一份线索。</small>':campusLink('collect:'+campusPanel,campus.evidence.includes(campusPanel)?'✓ 已记入线索簿':'记入线索簿')}${campusLink('notebook','打开失物档案')}${campusLink('close','回到应用')}</section>`;return `<section class="campus-paper"><small>校园传说 / 第02案 / 本机存档</small><h2>七点十七的来电</h2>${!campus.started?`<p>晚自习后，你在东楼捡到一部${escapeHTML(phoneModels[phoneState.model]?.name||'旧手机')}。它突然响了。校园里流传，这个时间不能接电话。</p><p>手机是谁的？来电、签名与借用记录，谁说的才是真话？</p>${campusLink('start','拿起手机，查看那条短信')}`:`<p>拾得设备：${escapeHTML(phoneModels[campus.device]?.name||'旧手机')}<br>证据 ${campus.evidence.length}/6 · ${campus.solved?'已归还':'寻找机主'}</p><div class="campus-evidence">${campus.evidence.length?campus.evidence.map(k=>campusLink('review:'+k,'重读 · '+campusClues[k].title)).join(''):'<p>还没有记下记录。先看看这部手机里留下了什么。</p>'}</div><p>你记下的记录可以点开重读。先分清谁在借用、谁是物主，再考虑声音来自哪里。不确定时可以继续调查，或主动翻提示。</p>${campusFeedback?`<p class="campus-feedback" role="status">${campusFeedback}</p>`:''}${!campus.solved?`<form data-campus-solve><label>手机的物主<select name="owner" required><option value="">选择</option><option value="zhou">短信落款：周遥</option><option value="chen">网名听风：陈默</option><option value="xia">QQ好友：小夏</option></select></label><label>四位手机锁码<input name="code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" aria-label="校园案件锁码" required></label><label>铃声的真实来源<select name="truth" required><option value="">选择</option><option value="ghost">校园传说是真的</option><option value="broadcast">广播社录音机定时试音</option><option value="alarm">物主的手机闹钟</option></select></label><button>核对并归还手机</button></form>`:'<p>✓ 手机已经物归原主。解锁陈默的动漫社留言。</p>'}${campusLink('hint','翻一页调查提示（免费）')}${campus.hints?`<p>${['','第一步，去短信读借用留言，再到相册查看设备签名。','QQ能把网名和姓名连起来。通讯录维修单写了生日与设锁方式。','物主是陈默；维修单生日6月12日→0612。论坛和录音都指向广播社定时试音。'][campus.hints]}</p>`:''}<details class="campus-notes"><summary>我的调查笔记</summary><form data-campus-notes><label>只保存在本机<textarea name="notes" aria-label="校园调查笔记" maxlength="1200" placeholder="哪两份记录能互相印证？">${escapeHTML(campus.notes||'')}</textarea></label><button>保存调查笔记</button></form></details>${campusLink('close','继续在应用间调查')}`}<p class="campus-note">全部为原创虚构剧情，不拨号、不收费、不收集真实通讯录。</p></section>`;}
function campusBrowserClue(){return campus.started&&/校园|七点|东楼|1917|0612/.test(ucQuery)?campusLink('forum','本机缓存：东楼19:17试音记录 / 校园BBS'):'';}
const campusSmsBase=phoneSmsMarkup,campusQQBase=phoneQQMarkup,campusForumBase=phoneCommunityMarkup,campusContactsBase=phoneContactsMarkup,campusMusicBase=extraPhoneScreen,campusScreenBase=phoneScreen,campusBrowserBase=phoneUCMarkup;
phoneSmsMarkup=function(){return campusPanel?campusMarkup():(smsView==='compose'||smsView==='message'?'':`<aside class="campus-incoming">✉ 东楼失物箱${campusLink(campus.started?'sms':'notebook',campus.started?'未署名短信：别相信那个来电传说':'一部捡来的手机，有一条未读短信')}</aside>`)+campusSmsBase();};
phoneQQMarkup=function(){return campusPanel?campusMarkup():(campus.started?campusLink('qq','小夏 [离线]：听风是谁？'):'')+campusQQBase();};
phoneCommunityMarkup=function(){return campusPanel?campusMarkup():(campus.started?campusLink('forum','[校园传说] 东楼19:17，铃声为什么自己响？'):'')+campusForumBase();};
phoneContactsMarkup=function(){return campusPanel?campusMarkup():(campus.started?campusLink('repair','修机师傅 / 六月十二日维修单'):'')+campusContactsBase();};
phoneUCMarkup=function(){return campusPanel?campusMarkup():campusBrowserClue()+campusBrowserBase();};
extraPhoneScreen=function(app){if(app==='campus')return campusMarkup();if(app==='anime')return animePocketMarkup();return campusMusicBase(app);};
phoneScreen=function(){if(typeof tide==='object'&&tide.active)return campusScreenBase();if(campusPanel&&['sms','qq','community','contacts','photos','music','browser','campus'].includes(phoneState.app))return campusMarkup();const base=campusScreenBase();if(campus.started&&phoneState.app==='photos')return campusLink('photo','相册附件：广播社报名单.jpg')+base;if(campus.started&&phoneState.app==='music')return campusLink('audio','本机录音：最后一段试音')+base;return base;};
systemApps.push({id:'campus',name:'失物档案',icon:'?',color:'yellow',desc:'校园传说：寻找这部手机的主人'},{id:'anime',name:'放学动漫社',icon:'漫',color:'orange',desc:'追番收藏、讨论与校园线索'});systemInstalled.push('campus','anime');phoneApps.push(['campus','失物档案','?'],['anime','放学动漫社','漫']);
const campusHubBase=explorationHubMarkup;
explorationHubMarkup=function(){return campusHubBase()+`<section class="campus-hub"><small>东楼失物箱 / 校园传说</small><h2>谁把手机，留在了七点十七？</h2><p>传说可以离奇，归还手机却需要证据。</p><button data-desk-open="campus">拿起这部失物手机 ›</button><button data-desk-open="anime">去放学动漫社 ›</button></section>`;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-campus]');if(!b)return;e.preventDefault();const action=b.dataset.campus;if(action.startsWith('review:')){const key=action.slice(7);if(!campus.evidence.includes(key)||!Object.hasOwn(campusClues,key))return;campusPanel=key;campusPhotoBack=key==='photo';}else if(action==='start'){campus.started=true;campus.device=phoneState.model;saveCampus();campusPanel='sms';}else if(action.startsWith('collect:')){campusCollect(action.slice(8));campusFeedback='这条线索已记下。回到应用间继续找其他证据。';campusPanel='notebook';}else if(action==='hint'){campus.hints=Math.min(3,campus.hints+1);saveCampus();}else campusPanel=action==='close'?'':Object.hasOwn(campusClues,action)||action==='notebook'?action:'';refreshPhone();});
document.addEventListener('click',e=>{if(e.target.closest('[data-desk-open],[data-phone-app],[data-system-launch],[data-phone-soft],[data-pc-app]'))campusPanel='';},true);
document.addEventListener('submit',e=>{if(!e.target.matches('[data-campus-solve]'))return;e.preventDefault();const f=new FormData(e.target);campusFeedback=campusSolve(f.get('owner'),String(f.get('code')||'').trim(),f.get('truth'));refreshPhone();});

let campusPinField=false;
document.addEventListener('focusin',e=>{if(e.target.matches?.('[aria-label="校园案件锁码"]'))campusPinField=true;else if(!e.target.closest?.('[data-phone-key],[data-phone-ok]'))campusPinField=false;});
const campusHardwareBase=extraHardwareAction;
extraHardwareAction=function(b){if(campusPinField&&document.querySelector('[data-campus-solve]')){const input=document.querySelector('[aria-label="校园案件锁码"]'),key=b.dataset.phoneKey;if(b.hasAttribute('data-phone-ok')){input?.closest('form')?.requestSubmit();return true;}if(input&&key!==undefined){if(/^[0-9]$/.test(key))input.value=(input.value+key).slice(0,4);else if(key==='*')input.value=input.value.slice(0,-1);else if(key==='#')input.focus();return true;}}return campusHardwareBase(b);};
document.addEventListener('click',e=>{if(e.target.closest('[data-campus-photo-turn]')){e.preventDefault();campusPhotoBack=!campusPhotoBack;refreshPhone();}});
let campusResetArmed=false;
const campusNotebookBase=campusMarkup;
campusMarkup=function(){const markup=campusNotebookBase();return !campusClues[campusPanel]&&campus.started?markup.replace('<p class="campus-note">','<button data-campus-reset>'+ (campusResetArmed?'再点一次，重开这个案件':'重玩这个案件')+'</button><p class="campus-note">'):markup;};
document.addEventListener('click',e=>{if(!e.target.closest('[data-campus-reset]'))return;e.preventDefault();if(!campusResetArmed){campusResetArmed=true;return refreshPhone();}campus={started:false,evidence:[],solved:false,hints:0,device:'',ending:'',notes:''};campusPanel='notebook';campusFeedback='';campusPhotoBack=false;campusResetArmed=false;saveCampus();refreshPhone();});

function campusSaveNotes(value){const before=campus.notes;campus.notes=String(value||'').slice(0,1200);if(!saveCampus()){campus.notes=before;return false;}return true;}
document.addEventListener('submit',e=>{if(!e.target.matches('[data-campus-notes]'))return;e.preventDefault();const saved=campusSaveNotes(new FormData(e.target).get('notes'));const button=e.target.querySelector('button');if(button)button.textContent=saved?'已保存到这部失物手机':'保存失败，请先复制笔记再重试';});
